import React from 'react';
import './Home.css';

function Home() {
  const twoWheelers = [
    {
      name: 'Yamaha R15',
      img: 'data:image/jpeg;base64,',
      link: '/product/yamaha-r15',
    },
    {
      name: 'Royal Enfield Classic 350',
      img: 'https://th.bing.com/th/id/OIP.HcWOj4BLgFs5NlEwOL7pYAHaE8?w=274&h=183&c=7&r=0&o=5&pid=1.7',
      link: '/product/royal-enfield-classic-350',
    },
    {
      name: 'Honda Shine',
      img: 'https://images.carandbike._Honda_Shine_100_10_63e67e6780.jpg',
      link: '/product/honda-shine',
    },
    {
      name: 'Scooty Zest 110',
      img: 'data:image/jpeg;base64,',
      link: '/product/scooty-zest-110',
    },
    {
      name: 'Bajaj Pulsar 125',
      img: 'data:image/jpeg;base64,',
      link: '/product/bajaj-pulsar-125',
    },
    {
      name: 'Hero Splendor Plus',
      img: 'https://th.bing.com/th/id/OIP.vBOArAewi52p2QozmW8bvQHaE8?w=261&h=180&c=7&r=0&o=5&pid=1.7',
      link: '/product/hero-splendor-plus',
    },
    {
      name: 'Bicycle MTB 26',
      img: 'data:image/jpeg;base64,',
      link: '/product/bicycle-mtb-26',
    },
    {
      name: 'Electric Scooter',
      img: 'https://th.bing.com/th/id/OIP.dVez20plauFq4VZG7rtVjwHaEK?w=320&h=202&c=7&r=0&o=5&pid=1.7',
      link: '/product/electric-scooter',
    },
    {
      name: 'Suzuki Gixxer SF',
      img: 'https://th.bing.com/th/id/OIP.ZP4V4tO5kax7GJ3qXW_jfQHaF7?w=302&h=203&c=7&r=0&o=5&pid=1.7',
      link: '/product/suzuki-gixxer-sf',
    },
    {
      name: 'TVS Apache RTR 160',
      img: 'https://th.bing.com/th/id/OIP.fhz6qVvv9VysSEp0l8Ot4wHaEo?w=314&h=209&c=7&r=0&o=5&pid=1.7',
      link: '/product/tvs-apache-rtr-160',
    },
    {
      name: 'KTM Duke 200',
      img: 'https://th.bing.com/th/id/OIP.L9lyvq5AW1frNIDstzzpCQHaE8?w=314&h=209&c=7&r=0&o=5&pid=1.7',
      link: '/product/ktm-duke-200',
    },
    {
      name: 'Honda Activa 6G',
      img: 'https://th.bing.com/th/id/OIP.7dRqlwW7dzxVfpznRl5lTQHaHa?w=314&h=209&c=7&r=0&o=5&pid=1.7',
      link: '/product/honda-activa-6g',
    },
    {
      name: 'Vespa SXL 150',
      img: 'https://th.bing.com/th/id/OIP.P88wKnJ9QmJHR7GBBeJuqgHaHa?w=310&h=207&c=7&r=0&o=5&pid=1.7',
      link: '/product/vespa-sxl-150',
    },
    {
      name: 'Aprilia SR 150',
      img: 'https://th.bing.com/th/id/OIP.iEmdePyYmFfepWGeKK7XYwHaF7?w=302&h=204&c=7&r=0&o=5&pid=1.7',
      link: '/product/aprilia-sr-150',
    },
    {
      name: 'Mahindra Mojo 300',
      img: 'https://th.bing.com/th/id/OIP.ihMzLf6g91bK2mKrANHj4gHaF4?w=322&h=213&c=7&r=0&o=5&pid=1.7',
      link: '/product/mahindra-mojo-300',
    },
  ];

  return (
    <div className="home">
      <h1>Welcome to TwoWheeler</h1>
      <p>Buy or rent your favorite bikes, scooters, and bicycles at the best prices!</p>

      <div className="product-grid">
        {twoWheelers.map((twoWheeler, index) => (
          <div className="product-card" key={index}>
            <img src={twoWheeler.img} alt={twoWheeler.name} />
            <h3>{twoWheeler.name}</h3>
            <a href={twoWheeler.link} className="btn-view-details">View Details</a>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
